//! Shared generator inputs and outputs. Lives in its own file so the
//! orchestrator and the individual generators don't import each other.

const std = @import("std");
const ir = @import("../core/ir.zig");
const targets = @import("../core/targets.zig");

/// Which lifecycle a generated file has (decision D3).
pub const Tier = enum {
    /// Regenerated and overwritten on every run. Never hand-edited.
    generated,
    /// Written once, only if absent, and never touched again without --force.
    /// Exists so a user has a place to put code; contains no logic.
    user_scaffold,
};

pub const Lang = enum {
    go,
    python,
    c,
    /// The tiny Zig file the build step compiles as the library root so the
    /// ABI hash can be exported alongside the user's own exports.
    zig_glue,
};

pub const OutFile = struct {
    lang: Lang,
    /// Relative to that language's output root. Always '/'-separated.
    path: []const u8,
    bytes: []const u8,
    tier: Tier = .generated,
    /// True for files whose content is a compiled artifact copied in by the
    /// build step rather than text produced here.
    binary: bool = false,
};

pub const FileList = std.ArrayList(OutFile);

pub const GoOptions = struct {
    /// e.g. "github.com/me/zpdf-go". Used for go.mod; when null, no go.mod is
    /// written and the caller is assumed to have one.
    module_path: ?[]const u8 = null,
    /// Defaults to the library name.
    package_name: ?[]const u8 = null,
    /// purego version required in go.mod. Paired with `go_directive`: purego's
    /// own go.mod sets a minimum Go version, and `go build` refuses a module
    /// whose directive is lower. v0.9.0 works with Go 1.23, which keeps the
    /// generated bindings usable by the widest range of consumers; v0.11.0
    /// needs at least 1.25.0. Change both together.
    purego_version: []const u8 = "v0.9.0",
    /// The `go` directive written into a generated go.mod.
    go_directive: []const u8 = "1.23",
};

pub const PythonOptions = struct {
    /// Import package name; defaults to the library name.
    package_name: ?[]const u8 = null,
    /// Distribution name on PyPI; defaults to the package name.
    dist_name: ?[]const u8 = null,
    /// Written only when true and the file is absent.
    emit_pyproject: bool = true,
};

pub const Context = struct {
    api: *const ir.Api,
    /// Already computed by the orchestrator; generators must not recompute.
    abi_hash: u64,
    /// 16 lowercase hex digits.
    abi_hash_hex: []const u8,
    targets: []const targets.Target,
    link_libc: bool,
    /// zbridge's own version, for the "Code generated by" header.
    version: []const u8,
    /// Path of the input .zig file as the user spelled it, for the header.
    input_path: []const u8,
    go: GoOptions = .{},
    python: PythonOptions = .{},

    pub fn libName(self: Context) []const u8 {
        return self.api.lib_name;
    }

    pub fn goPackage(self: Context) []const u8 {
        return self.go.package_name orelse self.api.lib_name;
    }

    pub fn pythonPackage(self: Context) []const u8 {
        return self.python.package_name orelse self.api.lib_name;
    }

    /// Lowered logical arguments for a function, allocated in `arena`.
    pub fn lower(self: Context, arena: std.mem.Allocator, f: ir.Function) ![]ir.Logical {
        _ = self;
        return ir.lower(arena, f);
    }
};

/// The standard "don't edit this" banner, in the given comment syntax.
pub fn banner(arena: std.mem.Allocator, ctx: Context, comment: []const u8) ![]const u8 {
    return std.fmt.allocPrint(arena,
        \\{s} Code generated by zbridge {s}. DO NOT EDIT.
        \\{s} Source: {s}
        \\{s} ABI: {s}
    , .{ comment, ctx.version, comment, ctx.input_path, comment, ctx.abi_hash_hex });
}
